typedef void *napi_env;
typedef void *napi_value;
enum napi_valuetype {napi_string,napi_number};
enum napi_status {napi_ok,napi_invalid_arg};
napi_status napi_typeof(napi_env env,napi_value value,napi_valuetype *result){
    *result=napi_string;
    return napi_ok;
}
void Callback(napi_value key,napi_env env){napi_valuetype kind;auto status=napi_typeof(env,key,&kind);HILOG_INFO(1,"%{public}d %{public}d",status,kind);}

